//! Explicitly lossy Netscape/curl cookies.txt interoperability.
//!
//! This format preserves domain scope, path, Secure, HttpOnly, expiry,
//! name, and value. It cannot preserve SameSite, CHIPS partition keys, or
//! original creation/access time, so callers must acknowledge that downgrade
//! on every operation. Partitioned cookies are omitted rather than flattened
//! into unsafe unpartitioned state.

const std = @import("std");
const snapshot = @import("snapshot.zig");

pub const header =
    "# Netscape HTTP Cookie File\n" ++
    "# Generated by netz. Full metadata requires the binary snapshot.\n\n";

pub const Options = struct {
    acknowledge_metadata_loss: bool = false,
    include_session: bool = false,
};

pub const Error = std.mem.Allocator.Error || error{
    InvalidNetscapeFile,
    MetadataLossNotAcknowledged,
    UnrepresentableCookie,
    SnapshotLimitExceeded,
};

pub fn encode(
    cookies: anytype,
    now_unix_seconds: i64,
    options: Options,
    out: *std.ArrayList(u8),
    allocator: std.mem.Allocator,
) Error!void {
    if (!options.acknowledge_metadata_loss) {
        return error.MetadataLossNotAcknowledged;
    }
    const start = out.items.len;
    errdefer out.shrinkRetainingCapacity(start);
    try out.appendSlice(allocator, header);
    var expiration_buffer: [32]u8 = undefined;
    for (cookies) |cookie| {
        if (cookie.partition_site != null) continue;
        if (cookie.expires_at) |deadline| {
            if (deadline <= now_unix_seconds) continue;
        } else if (!options.include_session) continue;
        if (!representable(cookie.name) or !representable(cookie.value) or
            !representable(cookie.domain) or !representable(cookie.path))
        {
            return error.UnrepresentableCookie;
        }
        if (cookie.http_only) try out.appendSlice(allocator, "#HttpOnly_");
        if (!cookie.host_only) try out.append(allocator, '.');
        try out.appendSlice(allocator, cookie.domain);
        try out.appendSlice(
            allocator,
            if (cookie.host_only) "\tFALSE\t" else "\tTRUE\t",
        );
        try out.appendSlice(allocator, cookie.path);
        try out.appendSlice(
            allocator,
            if (cookie.secure) "\tTRUE\t" else "\tFALSE\t",
        );
        const expiration = if (cookie.expires_at) |deadline|
            std.fmt.bufPrint(&expiration_buffer, "{d}", .{deadline}) catch
                unreachable
        else
            "0";
        try out.appendSlice(allocator, expiration);
        try out.append(allocator, '\t');
        try out.appendSlice(allocator, cookie.name);
        try out.append(allocator, '\t');
        try out.appendSlice(allocator, cookie.value);
        try out.append(allocator, '\n');
        if (out.items.len - start > snapshot.max_snapshot_bytes) {
            return error.SnapshotLimitExceeded;
        }
    }
}

pub fn decode(
    allocator: std.mem.Allocator,
    bytes: []const u8,
    max_records: usize,
    now_unix_seconds: i64,
    options: Options,
) Error!snapshot.Decoded {
    if (!options.acknowledge_metadata_loss) {
        return error.MetadataLossNotAcknowledged;
    }
    if (bytes.len > snapshot.max_snapshot_bytes) {
        return error.SnapshotLimitExceeded;
    }
    var lines = std.mem.splitScalar(u8, bytes, '\n');
    const first = trimCarriageReturn(lines.next() orelse
        return error.InvalidNetscapeFile);
    if (!std.mem.eql(u8, first, "# Netscape HTTP Cookie File") and
        !std.mem.eql(u8, first, "# HTTP Cookie File"))
    {
        return error.InvalidNetscapeFile;
    }

    var records: std.ArrayList(snapshot.Record) = .empty;
    errdefer {
        const decoded = snapshot.Decoded{
            .allocator = allocator,
            .saved_at = now_unix_seconds,
            .sequence = records.items.len,
            .records = records.items,
        };
        for (decoded.records) |*record| {
            if (!record.transferred) {
                allocator.free(record.name);
                allocator.free(record.value);
                allocator.free(record.domain);
                allocator.free(record.path);
            }
        }
        records.deinit(allocator);
    }

    while (lines.next()) |raw_line| {
        var line = trimCarriageReturn(raw_line);
        if (line.len == 0 or line[0] == '$') continue;
        var http_only = false;
        if (std.mem.startsWith(u8, line, "#HttpOnly_")) {
            http_only = true;
            line = line["#HttpOnly_".len..];
        } else if (line[0] == '#') continue;

        var fields: [7][]const u8 = undefined;
        var field_count: usize = 0;
        var split = std.mem.splitScalar(u8, line, '\t');
        while (split.next()) |field| {
            if (field_count == fields.len) return error.InvalidNetscapeFile;
            fields[field_count] = field;
            field_count += 1;
        }
        if (field_count != fields.len) return error.InvalidNetscapeFile;
        const domain_cookie = parseBool(fields[1]) orelse
            return error.InvalidNetscapeFile;
        const secure = parseBool(fields[3]) orelse
            return error.InvalidNetscapeFile;
        var domain = fields[0];
        if (domain.len != 0 and domain[0] == '.') domain = domain[1..];
        if (domain.len == 0 or fields[2].len == 0 or fields[2][0] != '/') {
            return error.InvalidNetscapeFile;
        }
        const expires_at: ?i64 = if (fields[4].len == 0 or
            std.mem.eql(u8, fields[4], "0"))
            null
        else
            std.fmt.parseInt(i64, fields[4], 10) catch
                return error.InvalidNetscapeFile;
        if (expires_at == null and !options.include_session) continue;
        if (expires_at) |deadline| if (deadline <= now_unix_seconds) continue;
        if (records.items.len == max_records) {
            return error.SnapshotLimitExceeded;
        }
        const name = try allocator.dupe(u8, fields[5]);
        errdefer allocator.free(name);
        const value = try allocator.dupe(u8, fields[6]);
        errdefer allocator.free(value);
        const owned_domain = try allocator.alloc(u8, domain.len);
        errdefer allocator.free(owned_domain);
        for (domain, owned_domain) |byte, *destination| {
            destination.* = std.ascii.toLower(byte);
        }
        const path = try allocator.dupe(u8, fields[2]);
        errdefer allocator.free(path);
        const partition_site = try allocator.dupe(u8, "");
        errdefer allocator.free(partition_site);
        const order: u64 = @intCast(records.items.len + 1);
        try records.append(allocator, .{
            .name = name,
            .value = value,
            .domain = owned_domain,
            .path = path,
            .expires_at = expires_at,
            .secure = secure,
            .http_only = http_only,
            .host_only = !domain_cookie,
            .partitioned = false,
            .partition_site = partition_site,
            .partition_secure = false,
            .partition_cross_site_ancestor = false,
            .same_site = 0,
            .created_at = now_unix_seconds,
            .creation_order = order,
            .last_access_order = order,
        });
    }
    return .{
        .allocator = allocator,
        .saved_at = now_unix_seconds,
        .sequence = records.items.len,
        .records = try records.toOwnedSlice(allocator),
    };
}

fn parseBool(value: []const u8) ?bool {
    if (std.ascii.eqlIgnoreCase(value, "TRUE")) return true;
    if (std.ascii.eqlIgnoreCase(value, "FALSE")) return false;
    return null;
}

fn representable(value: []const u8) bool {
    return std.mem.indexOfAny(u8, value, "\t\r\n") == null;
}

fn trimCarriageReturn(value: []const u8) []const u8 {
    return if (value.len != 0 and value[value.len - 1] == '\r')
        value[0 .. value.len - 1]
    else
        value;
}
